int checks=0;
void require(bool ok,const char* message){++checks;if(!ok)throw std::runtime_error(message);}
void near(double a,double b){require(std::abs(a-b)<1e-6,"Native/GLB pose coordinate mismatch");}
template<class F>void fails(const std::string& code,F fn){try{fn();}catch(const Error& e){require(e.code==code,("Expected "+code+", got "+e.code+": "+e.what()).c_str());return;}throw std::runtime_error("Expected "+code);}
struct Temp{fs::path root=fs::temp_directory_path()/path_from_utf8("cad-visual-service-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));Temp(){directory(root);}~Temp(){std::error_code e;fs::remove_all(root,e);}};
Json call(Service& s,const std::string& tool,const Json& args){for(int n=0;;++n){try{return s.call(tool,args);}catch(const Error& e){if(e.code!="workspace_busy"||n==1000)throw;}std::this_thread::sleep_for(std::chrono::milliseconds(2));}}
Json ready(Service& s){for(int n=0;n<10000;++n){auto r=call(s,"cad_viewer",{{"action","sync"},{"view_id","sequence"}});if(r.at("state")=="ready")return r;if(r.at("state")!="loading")throw std::runtime_error(r.dump());std::this_thread::sleep_for(std::chrono::milliseconds(2));}throw std::runtime_error("View timeout");}
std::uint32_t u32(const std::string& b,std::size_t p){std::uint32_t n=0;for(int k=0;k<4;++k)n|=std::uint32_t(static_cast<unsigned char>(b.at(p+k)))<<(8*k);return n;}
struct Glb{Json json;std::string binary;};
Glb read_glb(const Json& result){const auto b=read_text(path_from_utf8(text_field(result,"path")),64*1024*1024);require(u32(b,0)==0x46546c67&&u32(b,4)==2&&u32(b,8)==b.size(),"Native Service publishes valid GLB2");require(text_field(result,"sha256")==sha256(b),"Native GLB file hash");const auto n=u32(b,12);require(u32(b,16)==0x4e4f534a&&u32(b,24+n)==0x004e4942,"Independent GLB chunk types");return {parse_json(b.substr(20,n),64*1024*1024),b.substr(28+n)};}
std::vector<double> accessor(const Glb& g,std::size_t index){const auto& a=g.json.at("accessors").at(index);const auto& v=g.json.at("bufferViews").at(a.at("bufferView").get<std::size_t>());const auto width=a.at("type")=="SCALAR"?1:a.at("type")=="VEC3"?3:4;const auto offset=v.at("byteOffset").get<std::size_t>(),count=a.at("count").get<std::size_t>()*width;require(a.at("componentType")==5126&&offset+count*4<=g.binary.size(),"Independent accessor bounds");std::vector<double> out;for(std::size_t n=0;n<count;++n)out.push_back(std::bit_cast<float>(u32(g.binary,offset+4*n)));return out;}
Json presentation(double distance=0){Json directions=Json::array();for(const auto* id:{"ground","lever","slide","spindle"})directions.push_back({{"part_id",id},{"direction",{1,0,0}}});return {{"clip",nullptr},{"explode",{{"distance_mm",distance},{"directions",directions}}}};}
Json frame(double time,double angle,double travel,double distance=0){return {{"time_s",time},{"presentation",presentation(distance)},{"joints",Json::array({{{"assembly_id","mechanism"},{"values",Json::array({{{"mate_id","hinge"},{"coordinate","angle_deg"},{"value",angle}},{{"mate_id","spindle_joint"},{"coordinate","travel_mm"},{"value",travel}}})}}})}};}
void run(){
 Temp t;Service s(t.root);Json model={{"schema_version",1},{"units","mm"},{"parameters",Json::object()},{"features",Json::array({{{"id","box"},{"type","box"},{"size",{20,10,6}}}})},{"output","box"}};call(s,"cad_create",{{"document_id","box"},{"model",model}});const auto head=read_text(t.root/"documents/box/HEAD.json");
 Json settings={{"width",128},{"height",128},{"camera",{{"yaw",0},{"pitch",std::acos(-1.)/2},{"zoom",1},{"pan",{0,0}}}},
 {"render",{{"lighting",{{"enabled",false}}},{"background",{{"color",{1,1,1}}}},{"grid",false},{"axes",false},{"edges",false}}},{"appearance",{{"default_color",{1,0,0}},{"parts",Json::array()}}}};
 Json args={{"source",{{"document_id","box"},{"revision",1}}},{"settings",settings}};auto image=call(s,"cad_render",args);require(image.at("source").at("model_sha256")==sha256(model.dump())&&image.at("source").at("revision")==1,"Headless render source identity");
 const auto png=read_text(path_from_utf8(text_field(image,"path")),16*1024*1024);auto rgba=decode_png(png);require(rgba.width==128&&rgba.height==128&&text_field(image,"sha256")==sha256(png)&&image_unbase64(image.at("image").at("data"),2*1024*1024)==png,"Rendered PNG dimensions/hash/inline image agree");
 unsigned red=0;for(unsigned y=0;y<128;++y)for(unsigned x=0;x<128;++x){const auto offset=(y*128+x)*4;const bool expected=x>=20&&x<=107&&y>=42&&y<=85;const bool actual=rgba.pixels[offset]==255&&rgba.pixels[offset+1]==0&&rgba.pixels[offset+2]==0;require(expected==actual,"Analytic orthographic box silhouette and unlit color");red+=actual;}
 require(red==88*44,"Independent projected material area");require(image.at("downloads")[0].at("mimeType")=="image/png","Native PNG downloads use image MIME");const auto resource=s.read_resource(text_field(image.at("downloads")[0],"uri"));require(image_unbase64(resource.at("contents")[0].at("blob"),16*1024*1024)==png,"Rendered PNG resource independently reproduces bytes");
 auto job=call(s,"cad_job",{{"action","submit"},{"request_id","render_source"},{"tool","cad_render"},{"arguments",args}});for(int n=0;n<10000&&(job.at("state")=="queued"||job.at("state")=="running");++n){std::this_thread::sleep_for(std::chrono::milliseconds(2));job=call(s,"cad_job",{{"action","get"},{"job_id",job.at("job_id")}});}require(job.at("state")=="succeeded","Asynchronous native rendering completes");require(job.at("result").at("source")==image.at("source")&&job.at("result").at("sha256")==image.at("sha256"),"Render job pins the same source and deterministic pixels");
 args["settings"]["presentation"]={{"clip",{{"normal",{1,0,0}},{"offset_mm",10},{"keep","positive"}}},{"explode",{{"distance_mm",0},{"directions",Json::array()}}}};auto clipped=decode_png(read_text(path_from_utf8(text_field(call(s,"cad_render",args),"path")),16*1024*1024));unsigned clipped_red=0;for(std::size_t n=0;n<clipped.pixels.size();n+=4)clipped_red+=clipped.pixels[n]==255&&clipped.pixels[n+1]==0&&clipped.pixels[n+2]==0;require(clipped_red==red/2,"World clipping removes exactly half the analytic silhouette");
 args["inline_image"]=false;require(!call(s,"cad_render",args).contains("image"),"Headless file-only output explicit");auto bad=args;bad["settings"]["width"]=2049;fails("invalid_argument",[&]{call(s,"cad_render",bad);});bad=args;bad["settings"]["render"]["code"]="x";fails("invalid_argument",[&]{call(s,"cad_render",bad);});require(read_text(t.root/"documents/box/HEAD.json")==head,"Headless render preserves model HEAD");
 const auto fixture=parse_json(read_text(path_from_utf8(CAD_SOURCE_DIR)/"examples/articulated-arm.create.json"));call(s,"cad_create",fixture);call(s,"cad_open",{{"document_id","articulated_arm"},{"view_id","sequence"}});const auto shown=ready(s),eid=shown.at("evaluation_id");const auto arm_head=read_text(t.root/"documents/articulated_arm/HEAD.json");
 Json sequence={{"name","Native export"},{"frames",Json::array({frame(0,0,0),frame(2,90,18,20)})}};call(s,"cad_viewer",{{"action","sequence"},{"operation","save"},{"view_id","sequence"},{"evaluation_id",eid},{"sequence",sequence}});
 Json exported_args={{"document_id","articulated_arm"},{"revision",1},{"format","glb"},{"appearance",{{"default_color",{.1,.3,.6}},{"material",{{"opacity",.7},{"finish","metal"}}},{"parts",Json::array()}}}};auto static_export=call(s,"cad_export",exported_args);auto static_glb=read_glb(static_export);require(static_export.at("units")=="m"&&static_export.at("source_units")=="mm"&&static_export.at("mesh_count")==4&&static_export.at("sample_count")==0,"Static GLB uses metres with four leaves and captured source units");require(!static_glb.json.contains("animations"),"Static export has no invented animation");require(static_export.at("downloads")[0].at("mimeType")=="model/gltf-binary","GLB host resource MIME");
 exported_args["animation"]={{"view_id","sequence"},{"sequence_name","Native export"},{"sample_rate_hz",2},{"max_frames",8}};auto animated_export=call(s,"cad_export",exported_args);auto animated=read_glb(animated_export);require(animated_export.at("sample_count")==5&&animated.json.at("animations").size()==1,"Saved sequence includes both native endpoints and uniform samples");require(animated.json.at("extras").at("source").at("model_sha256")==animated_export.at("model_sha256")&&animated.json.at("extras").at("source").at("sequence_sha256")==animated_export.at("sequence_sha256"),"GLB retains source and exact saved recipe hashes");
 const auto& animation=animated.json.at("animations")[0];
 Json gif_args={{"source",{{"document_id","articulated_arm"},{"revision",1}}},{"format","gif"},{"animation",exported_args.at("animation")},{"loop",true},{"settings",settings}};
 const auto gif=call(s,"cad_render",gif_args);const auto gif_bytes=read_text(path_from_utf8(text_field(gif,"path")),64*1024*1024);
 require(gif.at("format")=="gif"&&gif.at("frame_count")==4&&gif.at("duration_s")==2&&gif.at("loop")==true,"Native GIF has four end-exclusive half-second frames and preserves duration");
 require(gif_bytes.substr(0,6)=="GIF89a"&&gif_bytes.back()==';'&&sha256(gif_bytes)==text_field(gif,"sha256")&&image_unbase64(gif.at("image").at("data"),2*1024*1024)==gif_bytes,"GIF file and MCP image bytes/hash agree");
 require(gif.at("source").at("sequence_sha256")==animated_export.at("sequence_sha256")&&gif.at("source").at("model_sha256")==animated_export.at("model_sha256"),"GIF and GLB capture the same immutable native sequence and model");
 require(gif.at("downloads")[0].at("mimeType")=="image/gif","Native GIF download MIME");
 require(image_unbase64(s.read_resource(text_field(gif.at("downloads")[0],"uri")).at("contents")[0].at("blob"),64*1024*1024)==gif_bytes,"GIF download reproduces bytes");
 auto gif_bad=gif_args;gif_bad["animation"]["max_frames"]=2;fails("limit_exceeded",[&]{call(s,"cad_render",gif_bad);});gif_bad=gif_args;gif_bad["settings"]["presentation"]=presentation();fails("invalid_argument",[&]{call(s,"cad_render",gif_bad);});gif_bad=gif_args;gif_bad["format"]="png";fails("invalid_argument",[&]{call(s,"cad_render",gif_bad);});
 for(const auto& channel:animation.at("channels"))if(channel.at("target").at("path")=="translation"){
  const auto& sampler=animation.at("samplers").at(channel.at("sampler").get<std::size_t>());const auto times=accessor(animated,sampler.at("input")),coordinates=accessor(animated,sampler.at("output"));const auto owner=text_field(animated.json.at("nodes").at(channel.at("target").at("node").get<std::size_t>()).at("extras"),"part_id");
  for(std::size_t n=0;n<times.size();++n){near(times[n],n*.5);auto pose=call(s,"cad_preview",{{"document_id","articulated_arm"},{"expected_revision",1},{"kind","mesh"},{"operations",Json::array({{{"op","set_joint_value"},{"assembly_id","mechanism"},{"mate_id","hinge"},{"coordinate","angle_deg"},{"value",45*times[n]}},{{"op","set_joint_value"},{"assembly_id","mechanism"},{"mate_id","spindle_joint"},{"coordinate","travel_mm"},{"value",9*times[n]}}})}});for(const auto& part:pose.at("summary").at("assembly").at("parts"))if(part.at("id")==owner)for(int axis=0;axis<3;++axis)near(coordinates[n*3+axis],(number(part.at("transform").at(axis*4+3))+(axis==0?10*times[n]:0))/1000.);}
 }
 require(read_text(t.root/"documents/articulated_arm/HEAD.json")==arm_head,"Visual exports/previews preserve editable source HEAD");
 auto capped=exported_args;capped["animation"]["max_frames"]=2;fails("limit_exceeded",[&]{call(s,"cad_export",capped);});capped=exported_args;capped["format"]="stl";fails("invalid_argument",[&]{call(s,"cad_export",capped);});
 call(s,"cad_apply",{{"document_id","articulated_arm"},{"expected_revision",1},{"operations",Json::array({{{"op","set_joint_value"},{"assembly_id","mechanism"},{"mate_id","hinge"},{"coordinate","angle_deg"},{"value",15}}})}});capped=exported_args;capped["revision"]=2;fails("stale_selection",[&]{call(s,"cad_export",capped);});gif_bad=gif_args;gif_bad["source"]["revision"]=2;fails("stale_selection",[&]{call(s,"cad_render",gif_bad);});Service reopened(t.root);require(call(reopened,"cad_export",exported_args).at("revision")==1,"Historical native sequence export survives HEAD changes and service restart");require(call(reopened,"cad_render",gif_args).at("sha256")==gif.at("sha256"),"Historical GIF is deterministic after HEAD edits and service restart");
}
